[h2]BASIC[/h2]
[list]
[*]Open Tray = {T}
[*]Next Tray = {right _arrow}
[*]Prev Tray = {left_arrow}
[*]Shuffle = {S}
[*]Highlight = {H}
[*]Clear Table = {F}
[*]Table Color= {C}
[*]Pool Color= {V}
[*]Zoom = {Z} / {mouse_wheel}
[*]Reference Image = {R}
[*]Image Guide = {G}
[*]Open Menu = {tab}
[*]Fullscreen = {f11}
[*]Exit Puzzle = {esc}
[/list]
[h2]HINTS[/h2]
[list]
[*]Show Location = Hold Piece + {L}
[*]Correct Angle = Hold Piece + {A}
[*]Preview Image = {P}
[/list]
